  const int num_h_min = oh0 + pad_h - (kH - 1) * dil_h;
  const int num_h_max = oh0 + TILE_OH - 1 + pad_h;
  const int num_w_min = ow0 + pad_w - (kW - 1) * dil_w;
  const int num_w_max = ow0 + TILE_OW - 1 + pad_w;
  const int ih_min = (num_h_min > 0) ? (num_h_min / stride_h) : 0;
  const int iw_min = (num_w_min > 0) ? (num_w_min / stride_w) : 0;
  int ih_max = (num_h_max > 0) ? (num_h_max / stride_h) : 0;
  int iw_max = (num_w_max > 0) ? (num_w_max / stride_w) : 0;
  ih_max = min(ih_max, H_in - 1);
  iw_max = min(iw_max, W_in - 1);
  const int sh = ih_max - ih_min + 1;
  const int sw = iw_max - iw_min + 1;
  const int ic0 = g * C_in_pg;
  const float* x_base = input + ((long long)n * C_in + ic0) * in_hw;
