  for (int s = tid; s < stage_total; s += nthreads) {
    const int siw = s % sw;
    const int t2 = s / sw;
    const int sih = t2 % sh;
    const int ic = t2 / sh;
    s_in[s] = __ldg(x_base + (long long)ic * in_hw +
                    (long long)(ih_min + sih) * W_in + (iw_min + siw));
  }
  // Per-block lookup tables: dilated kernel offset t -> kernel tap index (or -1).
  const int lut_h_size = min(spanK_h + 1, LUT_CAP);
  const int lut_w_size = min(spanK_w + 1, LUT_CAP);
  int* s_kh = reinterpret_cast<int*>(s_in + stage_total);
  int* s_kw = s_kh + lut_h_size;
  for (int i = tid; i < lut_h_size; i += nthreads) {
    s_kh[i] = ((i % dil_h) == 0) ? (i / dil_h) : -1;
  }
  for (int i = tid; i < lut_w_size; i += nthreads) {
    s_kw[i] = ((i % dil_w) == 0) ? (i / dil_w) : -1;
  }
  __syncthreads();
  const int SP = TILE_OH * TILE_OW;
  const long long w_ic_stride = (long long)C_out_pg * kH * kW;
  const long long w_oc_stride = (long long)kH * kW;
  const int oc_chunks = (C_out_pg + 1) / 2;
  // Hoist the spatial site and its contributing input window out of the work loop:
  // blockDim.x is a multiple of TILE_OH*TILE_OW, so every work item of a thread
  // revisits the same (oh, ow) and only the output-channel chunk advances.
  const int sp_t = tid % SP;
  const int oh_t = oh0 + sp_t / TILE_OW;
  const int ow_t = ow0 + sp_t % TILE_OW;
  const bool sp_valid = (oh_t < H_out) && (ow_t < W_out);
