  const int num_h_tot = oh_t + pad_h;
  const int num_w_tot = ow_t + pad_w;
  int ih_lo = num_h_tot - spanK_h;
  ih_lo = (ih_lo > 0) ? (ih_lo + stride_h - 1) / stride_h : 0;
  ih_lo = max(ih_lo, ih_min);
  int iw_lo = num_w_tot - spanK_w;
  iw_lo = (iw_lo > 0) ? (iw_lo + stride_w - 1) / stride_w : 0;
  iw_lo = max(iw_lo, iw_min);
  const int ih_hi = min(num_h_tot / stride_h, ih_max);
  const int iw_hi = min(num_w_tot / stride_w, iw_max);
  // Register-block two output channels per spatial site to cut register pressure and lift occupancy.
  for (int linear = tid; linear < oc_chunks * SP; linear += nthreads) {
    if (!sp_valid) continue;
