    const int oc_local0 = oc_chunk * 2;
    const int oc0 = g * C_out_pg + oc_local0;
    const bool full_oc = (oc_local0 + 2 <= C_out_pg);
    float acc[2];
    if (full_oc) {
      const float b0 = (bias != nullptr) ? __ldg(bias + oc0 + 0) : 0.0f;
      const float b1 = (bias != nullptr) ? __ldg(bias + oc0 + 1) : 0.0f;
      acc[0] = b0; acc[1] = b1;
    } else {
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        acc[j] = (bias != nullptr && oc_local0 + j < C_out_pg) ? __ldg(bias + oc0 + j) : 0.0f;
      }
    }
    const float* w_base =
        weight + ((long long)ic0 * C_out_pg + oc_local0) * kH * kW;
    // Walk the contributing input pixels directly: the dilated kernel offset is
    // resolved to a tap index through a per-block shared-memory lookup table,
    // so the hot loop needs no integer division or modulo at all.
    for (int ih = ih_lo; ih <= ih_hi; ++ih) {
      const int t_h = num_h_tot - ih * stride_h;
      const int kh = (t_h < lut_h_size) ? s_kh[t_h]
                                        : (((t_h % dil_h) == 0) ? (t_h / dil_h) : -1);
      if (kh < 0) continue;
